@IsTest
private class WorkItemControllerTest {
    @TestSetup
    static void setup() {
        // Create Project Template
        Project_Template__c projectTemplate = new Project_Template__c(Name = 'Test Project Template', Description__c = 'Test template for projects');
        insert as user projectTemplate;

        // Create Work Item Templates - separate templates for each level
        Work_Item_Template__c milestoneTemplate = new Work_Item_Template__c(Name = 'Milestone Template', Description__c = 'Template for milestones');
        Work_Item_Template__c deliverableTemplate = new Work_Item_Template__c(Name = 'Deliverable Template', Description__c = 'Template for deliverables');
        Work_Item_Template__c taskTemplate = new Work_Item_Template__c(Name = 'Task Template', Description__c = 'Template for tasks');
        insert as user new List<Work_Item_Template__c>{ milestoneTemplate, deliverableTemplate, taskTemplate };

        // Create Test Project
        Project__c project = new Project__c(
            Name = 'Test Project',
            Status__c = 'Active',
            Start_Date__c = Date.today(),
            End_Date__c = Date.today().addDays(90),
            Project_Manager__c = UserInfo.getUserId(),
            Project_Template__c = projectTemplate.Id
        );
        insert as user project;

        // Create hierarchical Work Items (3 levels deep)
        List<Work_Item__c> workItems = new List<Work_Item__c>();

        // Level 0: Root Work Items (Milestones)
        for (Integer i = 0; i < 5; i++) {
            workItems.add(
                new Work_Item__c(
                    Work_Item_Name__c = 'Milestone ' + i,
                    Project__c = project.Id,
                    Work_Item_Template__c = milestoneTemplate.Id,
                    Status__c = 'Not Started',
                    Start_Date__c = Date.today().addDays(i * 10),
                    Due_Date__c = Date.today().addDays((i + 1) * 10),
                    Estimated_Hours__c = 100,
                    Actual_Hours__c = 0,
                    Summary__c = 'Test milestone ' + i
                )
            );
        }
        insert as user workItems;

        // Level 1: Child Work Items (Deliverables) - 2 per milestone
        List<Work_Item__c> level1Items = new List<Work_Item__c>();
        for (Work_Item__c parent : workItems) {
            for (Integer j = 0; j < 2; j++) {
                level1Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Deliverable ' + j,
                        Project__c = project.Id,
                        Work_Item_Template__c = deliverableTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = 'In Progress',
                        Start_Date__c = parent.Start_Date__c,
                        Due_Date__c = parent.Due_Date__c,
                        Estimated_Hours__c = 40,
                        Actual_Hours__c = 20,
                        Summary__c = 'Test deliverable for ' + parent.Work_Item_Name__c
                    )
                );
            }
        }
        insert as user level1Items;

        // Level 2: Grandchild Work Items (Tasks) - 3 per deliverable
        List<Work_Item__c> level2Items = new List<Work_Item__c>();
        for (Work_Item__c parent : level1Items) {
            for (Integer k = 0; k < 3; k++) {
                level2Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Task ' + k,
                        Project__c = project.Id,
                        Work_Item_Template__c = taskTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = k == 0 ? 'Complete' : 'Not Started',
                        Start_Date__c = parent.Start_Date__c,
                        Due_Date__c = parent.Due_Date__c,
                        Estimated_Hours__c = 10,
                        Actual_Hours__c = k == 0 ? 10 : 0,
                        Summary__c = 'Test task for ' + parent.Work_Item_Name__c
                    )
                );
            }
        }
        insert as user level2Items;

        // Total Work Items: 5 + (5*2) + (5*2*3) = 5 + 10 + 30 = 45 items
    }

