@IsTest
static void testGetWorkItemsForProject() {
    Project__c project = [SELECT Id FROM Project__c LIMIT 1];

    Test.startTest();
    WorkItemController.ProjectDataWrapper result = WorkItemController.getWorkItemsForProject(project.Id, 3);
    Test.stopTest();

    // Verify project data
    System.assertNotEquals(null, result, 'Should return ProjectDataWrapper');
    System.assertEquals(project.Id, result.projectId, 'Should return correct project ID');
    System.assertNotEquals(null, result.projectStartDate, 'Should return project start date');
    System.assertNotEquals(null, result.projectDueDate, 'Should return project due date');

    // Verify root level items
    System.assertEquals(5, result.workItems.size(), 'Should return 5 root Work Items');

    // Verify first level children
    WorkItemController.WorkItemWrapper firstMilestone = result.workItems[0];
    System.assertEquals(2, firstMilestone.children.size(), 'Each milestone should have 2 deliverables');

    // Verify second level children
    WorkItemController.WorkItemWrapper firstDeliverable = firstMilestone.children[0];
    System.assertEquals(3, firstDeliverable.children.size(), 'Each deliverable should have 3 tasks');

    // Verify depth tracking
    System.assertEquals(0, firstMilestone.depth, 'Root item should have depth 0');
    System.assertEquals(1, firstDeliverable.depth, 'Level 1 item should have depth 1');
    System.assertEquals(2, firstDeliverable.children[0].depth, 'Level 2 item should have depth 2');

    // Verify progress calculation
    System.assert(firstDeliverable.progress > 0, 'Progress should be calculated for items with actual hours');

    // Verify wrapper fields populated correctly
    System.assertNotEquals(null, firstMilestone.id, 'Wrapper should have ID');
    System.assertNotEquals(null, firstMilestone.name, 'Wrapper should have name');
    System.assertNotEquals(null, firstMilestone.status, 'Wrapper should have status');
    System.assertNotEquals(null, firstMilestone.templateId, 'Wrapper should have template ID');
}

