        Test.stopTest();

        // Verify 5 resource assignments returned
        System.assertEquals(5, result.size(), 'Should return 5 resource assignments');

        // Verify all required fields populated
        for (Resource_Assignment__c assignment : result) {
            System.assertNotEquals(null, assignment.Id, 'Assignment should have ID');
            System.assertNotEquals(null, assignment.Resource_Classification__c, 'Assignment should have resource classification');
            System.assertEquals(UserInfo.getUserId(), assignment.Resource_User__c, 'Resource should be current user');
            System.assertNotEquals(null, assignment.Access_Level__c, 'Assignment should have access level');
