        Project__c project = [SELECT Id FROM Project__c LIMIT 1];

        Test.startTest();
        List<Resource_Assignment__c> result = ProjectResourceController.getResourceAssignments(project.Id);
        Test.stopTest();

        // Verify results are ordered by CreatedDate DESC (newest first)
